--- a/native/lambert.hpp
+++ b/native/lambert.hpp
@@ -99,37 +99,45 @@

 // Short error-free expansions retain cancellation-sensitive sums. The number
 // of terms is bounded at compile time (at most four), never dynamically allocated.
+struct Expansion {
+    double a=0., b=0., c=0., d=0.;
+    LB_HD double get(int i) const { return i==0 ? a : i==1 ? b : i==2 ? c : d; }
+    LB_HD void set(int i, double value) {
+        if (i==0) a=value;
+        else if(i==1) b=value;
+        else if(i==2) c=value;
+        else d=value;
+    }
+};
 template <int N> LB_HD double small_sum(const double (&values)[N]) {
-    double partial[N];
-    int count = 0;
-    for (int j = 0; j < N; ++j) {
-        double x = values[j];
-        int next = 0;
-        for (int k = 0; k < count; ++k) {
-            double y = partial[k];
-            if (::fabs(x) < ::fabs(y)) {
-                double temp = x;
-                x = y;
-                y = temp;
-            }
-            double high = x + y, low = y - (high - x);
-            if (!finite(high))
-                return missing;
-            if (low != 0.)
-                partial[next++] = low;
-            x = high;
-        }
-        partial[next] = x;
-        count = next + 1;
-    }
-    double total = 0.;
-    for (int k = 0; k < count; ++k)
-        total += partial[k];
+    Expansion partial;
+    int count=0;
+#pragma unroll
+    for(int j=0;j<N;++j) {
+        double x=values[j];
+        int next=0;
+#pragma unroll
+        for(int k=0;k<N;++k) {
+            if(k<count) {
+                double y=partial.get(k);
+                if(::fabs(x)<::fabs(y)) { double temp=x; x=y; y=temp; }
+                double high=x+y, low=y-(high-x);
+                if(!finite(high)) return missing;
+                if(low!=0.) partial.set(next++,low);
+                x=high;
+            }
+        }
+        partial.set(next,x);
+        count=next+1;
+    }
+    double total=0.;
+#pragma unroll
+    for(int k=0;k<N;++k) { if(k<count) total+=partial.get(k); }
     return total;
 }
